import openpyxl, re
from openpyxl.utils import get_column_letter as gl
wb = openpyxl.load_workbook("input.xlsx")
ws = wb["Model"]
def norm(f):
    s = re.sub(r"(\$?[A-Z]{1,2})\$?\d+", r"\1#", f)
    s = s.replace("$","")
    return s
for r in range(1,336):
    # group1 columns C..M, group2 O..S
    for rng in [range(3,14), range(15,20)]:
        items=[]
        for c in rng:
            v=ws.cell(r,c).value
            if isinstance(v,str) and v.startswith("="):
                items.append((gl(c),norm(v)))
        if len(items)>=3:
            from collections import Counter
            cnt=Counter(x[1] for x in items)
            if len(cnt)>1:
                common,mn=cnt.most_common(1)[0]
                if mn>=2:
                    odd=[x for x in items if x[1]!=common]
                    print(r, odd, "vs", common)
EOF

